/** TransactionsGetRequest defines the request schema for `/transactions/get` */
export type TransactionsGetRequest = {
  client_id?: ApiClientId;
  options?: TransactionsGetRequestOptions;
  access_token: AccessToken;
  secret?: ApiSecret;
  /** The earliest date for which data should be returned. Dates should be formatted as YYYY-MM-DD. */
  start_date: string;
  /** The latest date for which data should be returned. Dates should be formatted as YYYY-MM-DD. */
  end_date: string;
};

/** Indicates which version of the personal finance category taxonomy is being used. [View PFCv2 and PFCv1 taxonomies](https://plaid.com/documents/pfc-taxonomy-all.csv).  If you enabled Transactions or Enrich before December 2025 you will receive the `v1` taxonomy by default and may request `v2` by explicitly setting this field to `v2` in the request.  If you enabled Transactions or Enrich on or after December 2025, you may only receive the `v2` taxonomy. */
export type PersonalFinanceCategoryVersion = "v1" | "v2";

/** An optional object to be used with the request. If specified, `options` must not be `null`. */
export type TransactionsGetRequestOptions = {
  /** A list of `account_ids` to retrieve for the Item  Note: An error will be returned if a provided `account_id` is not associated with the Item. */
  account_ids?: (string)[];
  /** The number of transactions to fetch. */
  count?: number;
  /** The number of transactions to skip. The default value is 0. */
  offset?: number;
  /** Include the raw unparsed transaction description from the financial institution. */
  include_original_description?: boolean | null;
  /** Personal finance categories are now returned by default. */
  include_personal_finance_category_beta?: boolean;
  /** Personal finance categories are now returned by default. */
  include_personal_finance_category?: boolean;
  /** Counterparties and extra merchant fields are now returned by default. */
  include_logo_and_counterparty_beta?: boolean;
  personal_finance_category_version?: PersonalFinanceCategoryVersion;
  /** This field only applies to calls for Items where the Transactions product has not already been initialized (i.e. by specifying `transactions` in the `products`, `optional_products`, or `required_if_consented_products` array when calling `/link/token/create` or by making a previous call to `/transactions/sync` or `/transactions/get`). In those cases, the field controls the maximum number of days of transaction history that Plaid will request from the financial institution. The more transaction history is requested, the longer the historical update poll will take. If no value is specified, 90 days of history will be requested by default. In Production, if a value under 30 is provided, a minimum of 30 days of history will be requested.  If you are initializing your Items with transactions during the `/link/token/create` call (e.g. by including `transactions` in the `/link/token/create` `products` array), you must use the [`transactions.days_requested`](https://plaid.com/docs/api/link/#link-token-create-request-transactions-days-requested) field in the `/link/token/create` request instead of in the `/transactions/get` request.  If the Item has already been initialized with the Transactions product, this field will have no effect. The maximum amount of transaction history to request on an Item cannot be updated if Transactions has already been added to the Item. To request older transaction history on an Item where Transactions has already been added, you must delete the Item via `/item/remove` and send the user through Link to create a new Item.  Customers using [Recurring Transactions](https://plaid.com/docs/api/products/transactions/#transactionsrecurringget) should request at least 180 days of history for optimal results. */
  days_requested?: number;
};

/** TransactionsGetResponse defines the response schema for `/transactions/get` */
export type TransactionsGetResponse = {
  /** An array containing the `accounts` associated with the Item for which transactions are being returned. Each transaction can be mapped to its corresponding account via the `account_id` field. */
  accounts: (AccountBase)[];
  /** An array containing transactions from the account. Transactions are returned in reverse chronological order, with the most recent at the beginning of the array. The maximum number of transactions returned is determined by the `count` parameter. */
  transactions: (Transaction)[];
  /** The total number of transactions available within the date range specified. If `total_transactions` is larger than the size of the `transactions` array, more transactions are available and can be fetched via manipulating the `offset` parameter. */
  total_transactions: number;
  item: Item;
  request_id: RequestId;
  [key: string]: unknown;
};

