/** Reason why the item is about to be disconnected. `INSTITUTION_MIGRATION`: The institution is moving to API or to a different integration. For example, this can occur when an institution moves from a non-OAuth integration to an OAuth integration. `INSTITUTION_TOKEN_EXPIRATION`: The consent on an Item associated with a US or CA institution is about to expire. */
export type PendingDisconnectWebhookReason = "INSTITUTION_MIGRATION" | "INSTITUTION_TOKEN_EXPIRATION";

/** Fired when an Item is expected to be disconnected. The webhook will currently be fired 7 days before the existing Item is scheduled for disconnection. This can be resolved by having the user go through Link’s [update mode](http://plaid.com/docs/link/update-mode). Currently, this webhook is fired only for US or Canadian institutions; in the UK or EU, you should continue to listed for the [`PENDING_EXPIRATION`](https://plaid.com/docs/api/items/#pending_expiration) webhook instead. */
export type PendingDisconnectWebhook = {
  /** `ITEM` */
  webhook_type: string;
  /** `PENDING_DISCONNECT` */
  webhook_code: string;
  item_id: ItemId;
  user_id?: UserId;
  reason: PendingDisconnectWebhookReason;
  /** The date and time at which the Item is scheduled to disconnect, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format. */
  disconnect_time: string;
  environment: WebhookEnvironmentValues;
  [key: string]: unknown;
};

/** An object with keys of `account_id`'s that are mapped to their respective liabilities fields that changed.  Example: `{ "XMBvvyMGQ1UoLbKByoMqH3nXMj84ALSdE5B58": ["past_amount_due"] }` */
export type LiabilitiesAccountIdsWithUpdatedLiabilities = { [key: string]: (string)[] | undefined };

/** An error object and associated `item_id` used to identify a specific Item and error when a batch operation operating on multiple Items has encountered an error in one of the Items. */
export type Cause = PlaidError & { item_id?: ItemId } | null;

/** The ISO-4217 currency code of the payment. For standing orders and payment consents, `"GBP"` must be used. For Poland, Denmark, Sweden and Norway, only the local currency is currently supported. */
export type PaymentAmountCurrency = "GBP" | "EUR" | "PLN" | "SEK" | "DKK" | "NOK";

/** The amount and currency of a payment */
export type PaymentAmount = {
  currency: PaymentAmountCurrency;
  /** The amount of the payment. Must contain at most two digits of precision e.g. `1.23`. Minimum accepted value is `1`. */
  value: number;
};

/** The amount and currency of a payment */
export type PaymentAmountNullable = {
  currency: PaymentAmountCurrency;
  /** The amount of the payment. Must contain at most two digits of precision e.g. `1.23`. */
  value: number;
  [key: string]: unknown;
};

/** The amount and currency of a payment */
export type PaymentAmountToRefund = PaymentAmountNullable & { [key: string]: unknown };

/** The amount and currency of a payment */
export type PaymentAmountRefunded = PaymentAmountNullable & { [key: string]: unknown };

/** Life span for the payment consent. After the `to` date the payment consent expires and can no longer be used for payment initiation. */
export type PaymentConsentValidDateTime = {
  /** The date and time from which the consent should be active, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format. */
  from?: string | null;
  /** The date and time at which the consent expires, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format. */
  to?: string | null;
};

/** Defines consent payments limitations per period. */
export type PaymentConsentPeriodicAmount = {
  amount: PaymentConsentPeriodicAmountAmount;
  interval: PaymentConsentPeriodicInterval;
  alignment: PaymentConsentPeriodicAlignment;
};

/** Maximum cumulative amount for all payments in the specified interval. */
export type PaymentConsentPeriodicAmountAmount = PaymentAmount;

/** Payment consent periodic interval. */
export type PaymentConsentPeriodicInterval = "DAY" | "WEEK" | "MONTH" | "YEAR";

/** Where the payment consent period should start.  If the institution is Monzo, only `CONSENT` alignments are supported.  `CALENDAR`: line up with a calendar.  `CONSENT`: on the date of consent creation. */
export type PaymentConsentPeriodicAlignment = "CALENDAR" | "CONSENT";

