/** Object containing fraud risk data pertaining to the Item linked as part of the verification. */
export type PayrollRiskSignalsItem = {
  item_id: ItemId;
  /** Array of payroll income document authenticity data retrieved for each of the user's accounts. */
  verification_risk_signals: (DocumentRiskSignalsObject)[];
  [key: string]: unknown;
};

/** Object containing fraud risk data for a set of income documents. */
export type DocumentRiskSignalsObject = {
  /** ID of the payroll provider account. */
  account_id: string | null;
  /** Array of document metadata and associated risk signals per document */
  single_document_risk_signals: (SingleDocumentRiskSignal)[];
  /** Array of risk signals computed from a set of uploaded documents and the associated documents' metadata */
  multi_document_risk_signals: (MultiDocumentRiskSignal)[];
  [key: string]: unknown;
};

/** Object containing metadata for the document */
export type RiskSignalDocumentReference = {
  /** An identifier of the document referenced by the document metadata. */
  document_id?: string | null;
  /** The name of the document */
  document_name?: string;
  status?: RiskSignalDocumentStatus;
  document_type?: RiskSignalDocumentType;
  file_type?: RiskSignalFileType;
  [key: string]: unknown;
};

/** Type of a document for risk signal analysis */
export type RiskSignalDocumentType = "UNKNOWN" | "BANK_STATEMENT" | "BENEFITS_STATEMENT" | "BUSINESS_FILING" | "CHECK" | "DRIVING_LICENSE" | "FINANCIAL_STATEMENT" | "INVOICE" | "PAYSLIP" | "SOCIAL_SECURITY_CARD" | "TAX_FORM" | "UTILITY_BILL" | null;

/** The file type for risk signal analysis */
export type RiskSignalFileType = "UNKNOWN" | "IMAGE_PDF" | "SCAN_OCR" | "TRUE_PDF" | "IMAGE" | "MIXED_PAGE_PDF" | "EMPTY_PDF" | "FLATTENED_PDF" | null;

/** Status of a document for risk signal analysis */
export type RiskSignalDocumentStatus = "PROCESSING" | "PROCESSING_COMPLETE" | "PROCESSING_ERROR" | "PASSWORD_PROTECTED" | "VIRUS_DETECTED";

/** A summary across all risk signals associated with a document */
export type DocumentRiskSummary = {
  /** A number between 0 and 100, inclusive, where a score closer to 0 indicates a document is likely to be trustworthy and a score closer to 100 indicates a document is likely to be fraudulent. You can automatically reject documents with a high risk score, automatically accept documents with a low risk score, and manually review documents in between. We suggest starting with a threshold of 80 for auto-rejection and 20 for auto-acceptance. As you gather more data points on typical risk scores for your use case, you can tune these parameters to reduce the number of documents undergoing manual review. */
  risk_score: number | null;
  [key: string]: unknown;
};

/** Object containing all risk signals and relevant metadata for a single document */
export type SingleDocumentRiskSignal = {
  document_reference: RiskSignalDocumentReference;
  /** Array of attributes that indicate whether or not there is fraud risk with a document */
  risk_signals: (DocumentRiskSignal)[];
  risk_summary: DocumentRiskSummary;
  [key: string]: unknown;
};

/** Object containing risk signals and relevant metadata for a set of uploaded documents */
export type MultiDocumentRiskSignal = {
  /** Array of objects containing attributes that could indicate if a document is fraudulent */
  document_references: (RiskSignalDocumentReference)[];
  /** Array of attributes that indicate whether or not there is fraud risk with a set of documents */
  risk_signals: (DocumentRiskSignal)[];
  [key: string]: unknown;
};

