/** Metadata about an event that occurred while the user was going through Link */
export type LinkEventMetadata = {
  /** The error code that the user encountered. Emitted by `ERROR`, `EXIT`. */
  error_code?: string;
  /** The error message that the user encountered. Emitted by: `ERROR`, `EXIT`. */
  error_message?: string;
  /** The error type that the user encountered. Emitted by: `ERROR`, `EXIT`. */
  error_type?: string;
  /** The status key indicates the point at which the user exited the Link flow. Emitted by: `EXIT`. */
  exit_status?: string;
  /** The ID of the selected institution. Emitted by: all events. */
  institution_id?: string;
  /** The name of the selected institution. Emitted by: all events. */
  institution_name?: string;
  /** The query used to search for institutions. Emitted by: `SEARCH_INSTITUTION`. */
  institution_search_query?: string;
  /** The request ID for the last request made by Link. This can be shared with Plaid Support to expedite investigation. Emitted by: all events. */
  request_id?: string;
  /** If set, the user has encountered one of the following MFA types: code, device, questions, selections. Emitted by: `SUBMIT_MFA` and `TRANSITION_VIEW` when `view_name` is `MFA`. */
  mfa_type?: string;
  /** The name of the view that is being transitioned to. Emitted by: `TRANSITION_VIEW`. */
  view_name?: string;
  /** Either the verification method for a matched institution selected by the user or the Auth Type Select flow type selected by the user. If selection is used to describe selected verification method, then possible values are `phoneotp` or `password`;  if selection is used to describe the selected Auth Type Select flow, then possible values are `flow_type_manual` or `flow_type_instant`. Emitted by: `MATCHED_SELECT_VERIFY_METHOD` and `SELECT_AUTH_TYPE`. */
  selection?: string;
  /** The name of the selected brand. */
  brand_name?: string;
  /** The reason this institution was matched. This will be either `returning_user` or `routing_number` if emitted by `MATCHED_SELECT_INSTITUTION`. Otherwise, this will be `SAVED_INSTITUTION` or `AUTO_SELECT_SAVED_INSTITUTION` if emitted by `SELECT_INSTITUTION`. */
  match_reason?: string;
  /** The routing number submitted by user at the micro-deposits routing number pane. Emitted by `SUBMIT_ROUTING_NUMBER`. */
  routing_number?: string;
  /** The account number mask extracted from the user-provided account number. If the user-inputted account number is four digits long, `account_number_mask` is empty. Emitted by `SUBMIT_ACCOUNT_NUMBER`. */
  account_number_mask?: string;
  [key: string]: unknown;
};

/** An event that occurred while the user was going through Link */
export type LinkEvent = {
  /** Event name */
  event_name: string;
  /** Timestamp in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format. */
  timestamp: string;
  /** UUID that can be used to deduplicate events */
  event_id: string;
  event_metadata: LinkEventMetadata;
  [key: string]: unknown;
};

/** This webhook contains a summary of the events from a Link session and will be fired after the user finishes going through Link. If the user abandons the Link flow (i.e., closes the hosted link webpage or leaves Link open for too long without taking any action), the webhook will be fired 5-15 minutes after the last user interaction. A single Link session may occasionally generate multiple `EVENTS` webhooks. If this occurs, the new webhook will contain all previous events for the session, as well as new events that occurred since the previous `EVENTS` webhook was sent. If this occurs, events can be grouped using the `link_session_id` field and, if necessary, de-duplicated using the `event_id` field.  By default, the `EVENTS` webhook is sent only for sessions where the end user goes through a Hosted Link flow (including Link Recovery flows). If you would like to receive this webhook for sessions not using Hosted Link, contact your Account Manager or Support. This enablement will also cause you to receive the `SESSION_FINISHED` webhook for non-Hosted-Link sessions and to be able to use `/link/token/get` to receive events data for non-Hosted Link sessions. */
export type LinkEventsWebhook = {
  /** `LINK` */
  webhook_type: string;
  /** `EVENTS` */
  webhook_code: string;
  /** The Link events emitted during the Link session */
  events: (LinkEvent)[];
  /** An identifier for the Link session these events occurred in */
  link_session_id: string;
  /** The Link token used to create the Link session these events are from */
  link_token: string;
  [key: string]: unknown;
};

/** Fired when a user successfully adds a Plaid Item during a Link session when using Hosted Link or Multi-Item Link sessions. Contains the public token for the Item. */
export type ItemAddResultWebhook = {
  /** `LINK` */
  webhook_type: string;
  /** `ITEM_ADD_RESULT` */
  webhook_code: string;
  /** The identifier for the Link session. */
  link_session_id: string;
  /** The link token used to create the Link session. */
  link_token: string;
  /** The public token corresponding to the item that was added. */
  public_token: string;
  environment: WebhookEnvironmentValues;
  [key: string]: unknown;
};

/** Contains the state of a completed Link session, along with the public token(s) if available.  By default, this webhook is sent only for sessions enabled for the Hosted Link flow (including Link Recovery flows), a Multi-Item Link flow, or a Layer flow. If you would like to receive this webhook for other sessions, contact your Account Manager or Support. This enablement will also enable the `EVENTS` webhook for all Link sessions and the ability to use `/link/token/get` to retrieve events for non-Hosted-Link sessions. */
export type LinkSessionFinishedWebhook = {
  /** `LINK` */
  webhook_type: string;
  /** `SESSION_FINISHED` */
  webhook_code: string;
  /** The final status of the Link session. Will always be "SUCCESS" or "EXITED". */
  status: string;
  /** The identifier for the Link session. */
  link_session_id: string;
  /** The link token used to create the Link session. */
  link_token: string;
  /** The public token generated by the Link session. This field has been deprecated; please use `public_tokens` instead. */
  public_token?: string;
  /** The public tokens generated by the Link session. */
  public_tokens?: (string)[];
  user_id?: UserId;
  environment: WebhookEnvironmentValues;
  [key: string]: unknown;
};

/** Contains the state of a SMS same-day microdeposits verification session. */
export type HostedMmdVerificationWebhook = {
  /** `AUTH` */
  webhook_type: string;
  /** `SMS_MICRODEPOSITS_VERIFICATION` */
  webhook_code: string;
  /** The final status of the same-day microdeposits verification. Will always be `MANUALLY_VERIFIED` or `VERIFICATION_FAILED`. */
  status: string;
  item_id: ItemId;
  /** The external account ID of the affected account */
  account_id: string;
  environment?: WebhookEnvironmentValues;
  [key: string]: unknown;
};

