/** A representation of an Item within a Base Report. */
export type BaseReportItem = {
  /** The full financial institution name associated with the Item. */
  institution_name: string;
  /** The id of the financial institution associated with the Item. */
  institution_id: string;
  /** The date and time when this Item’s data was last retrieved from the financial institution, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format. */
  date_last_updated: string;
  item_id: ItemId;
  /** Data about each of the accounts open on the Item. */
  accounts: (BaseReportAccount)[];
  [key: string]: unknown;
};

/** Base Report information about an account */
export type BaseReportAccount = {
  /** Plaid’s unique identifier for the account. This value will not change unless Plaid can't reconcile the account with the data returned by the financial institution. This may occur, for example, when the name of the account changes. If this happens a new `account_id` will be assigned to the account.  If an account with a specific `account_id` disappears instead of changing, the account is likely closed. Closed accounts are not returned by the Plaid API.  Like all Plaid identifiers, the `account_id` is case sensitive. */
  account_id: string;
  balances: BaseReportAccountBalances;
  /** The information about previously submitted valid dispute statements by the consumer */
  consumer_disputes: (ConsumerDispute)[];
  /** The last 2-4 alphanumeric characters of an account's official account number. Note that the mask may be non-unique between an Item's accounts, and it may also not match the mask that the bank displays to the user. */
  mask: string | null;
  metadata: BaseReportAccountMetadata;
  /** The name of the account, either assigned by the user or by the financial institution itself */
  name: string;
  /** The official name of the account as given by the financial institution */
  official_name: string | null;
  type: AccountType;
  subtype: AccountSubtype;
  /** The duration of transaction history available within this report for this Item, typically defined as the time since the date of the earliest transaction in that account. */
  days_available: number;
  /** Transaction history associated with the account. Transaction history returned by endpoints such as `/transactions/get` or `/investments/transactions/get` will be returned in the top-level `transactions` field instead. Some transactions may have their details masked in accordance to the FCRA. These will appear with a `credit_category` of `MASKED_TRANSACTION_CATEGORY`. */
  transactions: (BaseReportTransaction)[];
  /** Data returned by the financial institution about the account owner or owners. For business accounts, the name reported may be either the name of the individual or the name of the business, depending on the institution. Multiple owners on a single account will be represented in the same `owner` object, not in multiple owner objects within the array. This array can also be empty if no owners are found. */
  owners: (Owner)[];
  ownership_type: OwnershipType;
  /** Calculated data about the historical balances on the account. Currently not supported by `brokerage` or `investment` accounts. */
  historical_balances?: (BaseReportHistoricalBalance)[];
  account_insights?: BaseReportAccountInsights;
  attributes?: BaseReportAttributes;
  [key: string]: unknown;
};

/** The information about a previously submitted valid dispute statement by the consumer */
export type ConsumerDispute = {
  /** (Deprecated) A unique identifier (UUID) of the consumer dispute that can be used for troubleshooting */
  consumer_dispute_id: string;
  /** Date of the disputed field (e.g. transaction date), in an ISO 8601 format (YYYY-MM-DD) */
  dispute_field_create_date: string;
  category: ConsumerDisputeCategory;
  /** Text content of dispute */
  statement: string;
  [key: string]: unknown;
};

/** Type of data being disputed by the consumer */
export type ConsumerDisputeCategory = "TRANSACTION" | "BALANCE" | "IDENTITY" | "OTHER";

/** Information about an account's balances. */
export type BaseReportAccountBalances = {
  /** The amount of funds available to be withdrawn from the account, as determined by the financial institution.  For `credit`-type accounts, the `available` balance typically equals the `limit` less the `current` balance, less any pending outflows plus any pending inflows.  For `depository`-type accounts, the `available` balance typically equals the `current` balance less any pending outflows plus any pending inflows. For `depository`-type accounts, the `available` balance does not include the overdraft limit.  For `investment`-type accounts (or `brokerage`-type accounts for API versions 2018-05-22 and earlier), the `available` balance is the total cash available to withdraw as presented by the institution.  Note that not all institutions calculate the `available`  balance. In the event that `available` balance is unavailable, Plaid will return an `available` balance value of `null`.  Available balance may be cached and is not guaranteed to be up-to-date in realtime unless the value was returned by `/accounts/balance/get`.  If `current` is `null` this field is guaranteed not to be `null`. */
  available: number | null;
  /** The total amount of funds in or owed by the account.  For `credit`-type accounts, a positive balance indicates the amount owed; a negative amount indicates the lender owing the account holder.  For `loan`-type accounts, the current balance is the principal remaining on the loan, except in the case of student loan accounts at Sallie Mae (`ins_116944`). For Sallie Mae student loans, the account's balance includes both principal and any outstanding interest.  For `investment`-type accounts (or `brokerage`-type accounts for API versions 2018-05-22 and earlier), the current balance is the total value of assets as presented by the institution.  Note that balance information may be cached unless the value was returned by `/accounts/balance/get`; if the Item is enabled for Transactions, the balance will be at least as recent as the most recent Transaction update. If you require realtime balance information, use the `available` balance as provided by `/accounts/balance/get`.  When returned by `/accounts/balance/get`, this field may be `null`. When this happens, `available` is guaranteed not to be `null`. */
  current: number | null;
  /** For `credit`-type accounts, this represents the credit limit.  For `depository`-type accounts, this represents the pre-arranged overdraft limit, which is common for current (checking) accounts in Europe.  In North America, this field is typically only available for `credit`-type accounts. */
  limit: number | null;
  /** The ISO-4217 currency code of the balance. Always null if `unofficial_currency_code` is non-null. */
  iso_currency_code: string | null;
  /** The unofficial currency code associated with the balance. Always null if `iso_currency_code` is non-null. Unofficial currency codes are used for currencies that do not have official ISO currency codes, such as cryptocurrencies and the currencies of certain countries.  See the [currency code schema](https://plaid.com/docs/api/accounts#currency-code-schema) for a full listing of supported `unofficial_currency_code`s. */
  unofficial_currency_code: string | null;
  /** Timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format (`YYYY-MM-DDTHH:mm:ssZ`) indicating the oldest acceptable balance when making a request to `/accounts/balance/get`.  This field is only used and expected when the institution is `ins_128026` (Capital One) and the Item contains one or more accounts with a non-depository account type, in which case a value must be provided or an `INVALID_REQUEST` error with the code of `INVALID_FIELD` will be returned. For Capital One depository accounts as well as all other account types on all other institutions, this field is ignored. See [account type schema](https://plaid.com/docs/api/accounts/#account-type-schema) for a full list of account types.  If the balance that is pulled is older than the given timestamp for Items with this field required, an `INVALID_REQUEST` error with the code of `LAST_UPDATED_DATETIME_OUT_OF_RANGE` will be returned with the most recent timestamp for the requested account contained in the response. */
  last_updated_datetime?: string | null;
  /** The average historical balance for the entire report */
  average_balance?: number | null;
  /** The average historical balance of each calendar month */
  average_monthly_balances?: (BaseReportAverageMonthlyBalances)[];
  /** The average historical balance from the most recent 30 days */
  most_recent_thirty_day_average_balance?: number | null;
};

/** Metadata about the extracted account. */
export type BaseReportAccountMetadata = {
  /** The beginning of the range of the financial institution provided data for the account, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format ("yyyy-mm-dd"). */
  start_date: string | null;
  /** The end of the range of the financial institution provided data for the account, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format ("yyyy-mm-dd"). */
  end_date: string | null;
};

/** A unique ID identifying an Base Report. Like all Plaid identifiers, this ID is case sensitive. */
export type BaseReportId = string;

/** A transaction on the Base Report */
export type BaseReportTransaction = {
  /** The ID of the account in which this transaction occurred. */
  account_id: string;
  /** The settled value of the transaction, denominated in the transaction's currency, as stated in `iso_currency_code` or `unofficial_currency_code`. Positive values when money moves out of the account; negative values when money moves in. For example, debit card purchases are positive; credit card payments, direct deposits, and refunds are negative. */
  amount: number;
  /** The ISO-4217 currency code of the transaction. Always `null` if `unofficial_currency_code` is non-null. */
  iso_currency_code: string | null;
  /** The unofficial currency code associated with the transaction. Always `null` if `iso_currency_code` is non-`null`. Unofficial currency codes are used for currencies that do not have official ISO currency codes, such as cryptocurrencies and the currencies of certain countries.  See the [currency code schema](https://plaid.com/docs/api/accounts#currency-code-schema) for a full listing of supported `unofficial_currency_code`s. */
  unofficial_currency_code: string | null;
  /** The merchant name or transaction description.  Note: This is a legacy field that is not actively maintained. Use `merchant_name` instead for the merchant name. */
  name?: string | null;
  /** The string returned by the financial institution to describe the transaction. */
  original_description: string | null;
  credit_category?: CreditCategory;
  /** The check number of the transaction. This field is only populated for check transactions. */
  check_number?: string | null;
  /** For pending transactions, the date that the transaction occurred; for posted transactions, the date that the transaction posted. Both dates are returned in an [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format ( `YYYY-MM-DD` ). */
  date: string;
  /** The date on which the transaction took place, in IS0 8601 format. */
  date_transacted?: string | null;
  location?: Location;
  /** The merchant name, as enriched by Plaid from the `name` field. This is typically a more human-readable version of the merchant counterparty in the transaction. For some bank transactions (such as checks or account transfers) where there is no meaningful merchant name, this value will be `null`. */
  merchant_name?: string | null;
  /** When `true`, identifies the transaction as pending or unsettled. Pending transaction details (name, type, amount, category ID) may change before they are settled. */
  pending: boolean;
  /** The name of the account owner. This field is not typically populated and only relevant when dealing with sub-accounts. */
  account_owner?: string | null;
  /** The unique ID of the transaction. Like all Plaid identifiers, the `transaction_id` is case sensitive. */
  transaction_id: string;
  transaction_type?: BaseReportTransactionType;
  /** A hierarchical array of the categories to which this transaction belongs. For a full list of categories, see [`/categories/get`](https://plaid.com/docs/api/products/transactions/#categoriesget). */
  category?: (string)[] | null;
  /** The ID of the category to which this transaction belongs. For a full list of categories, see [`/categories/get`](https://plaid.com/docs/api/products/transactions/#categoriesget). */
  category_id?: string | null;
  personal_finance_category?: PersonalFinanceCategory;
  [key: string]: unknown;
};

/** `digital:` transactions that took place online.  `place:` transactions that were made at a physical location.  `special:` transactions that relate to banks, e.g. fees or deposits.  `unresolved:` transactions that do not fit into the other types. */
export type BaseReportTransactionType = "digital" | "place" | "special" | "unresolved" | null;

/** Calculated insights derived from transaction-level data. This field has been deprecated in favor of [Base Report attributes aggregated across accounts](https://plaid.com/docs/api/products/check/#cra-check_report-base_report-get-response-report-attributes) and will be removed in a future release. */
export type BaseReportAccountInsights = {
  /** Date of the earliest transaction for the account. */
  oldest_transaction_date?: string | null;
  /** Date of the most recent transaction for the account. */
  most_recent_transaction_date?: string | null;
  /** Number of days days available for the account. */
  days_available?: number;
  /** Average number of days between sequential transactions */
  average_days_between_transactions?: number;
  /** Longest gap between sequential transactions in a time period. This array can include multiple time periods. */
  longest_gaps_between_transactions?: (BaseReportLongestGapInsights)[];
  /** The number of debits into the account. This array will be empty for non-depository accounts. */
  number_of_inflows?: (BaseReportNumberFlowInsights)[];
  /** Average amount of debit transactions into the account in a time period. This array will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
  average_inflow_amounts?: (BaseReportAverageFlowInsights)[];
  /** The number of outflows from the account. This array will be empty for non-depository accounts. */
  number_of_outflows?: (BaseReportNumberFlowInsights)[];
  /** Average amount of transactions out of the account in a time period. This array will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
  average_outflow_amounts?: (BaseReportAverageFlowInsights)[];
  /** Number of days with no transactions */
  number_of_days_no_transactions?: number;
  [key: string]: unknown;
};

/** Calculated attributes derived from transaction-level data. */
export type BaseReportAttributes = {
  /** Prediction indicator of whether the account is a primary account. Only one account per account type across the items connected will have a value of true. */
  is_primary_account?: boolean | null;
  /** Value ranging from 0-1. The higher the score, the more confident we are of the account being the primary account. */
  primary_account_score?: number | null;
  /** The number of net NSF fee transactions for a given account within the report time range (not counting any fees that were reversed within the time range). */
  nsf_overdraft_transactions_count?: number;
  /** The number of net NSF fee transactions within the last 30 days for a given account (not counting any fees that were reversed within the time range). */
  nsf_overdraft_transactions_count_30d?: number;
  /** The number of net NSF fee transactions within the last 60 days for a given account (not counting any fees that were reversed within the time range). */
  nsf_overdraft_transactions_count_60d?: number;
  /** The number of net NSF fee transactions within the last 90 days for a given account (not counting any fees that were reversed within the time range). */
  nsf_overdraft_transactions_count_90d?: number;
  total_inflow_amount?: TotalInflowAmount;
  total_inflow_amount_30d?: TotalInflowAmount30D;
  total_inflow_amount_60d?: TotalInflowAmount60D;
  total_inflow_amount_90d?: TotalInflowAmount90D;
  total_outflow_amount?: TotalOutflowAmount;
  total_outflow_amount_30d?: TotalOutflowAmount30D;
  total_outflow_amount_60d?: TotalOutflowAmount60D;
  total_outflow_amount_90d?: TotalOutflowAmount90D;
  [key: string]: unknown;
};

/** Total amount of debit transactions into the account in the time period of the report. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalInflowAmount = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of debit transactions into the account in the last 30 days. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalInflowAmount30D = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of debit transactions into the account in the last 60 days. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalInflowAmount60D = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of debit transactions into the account in the last 90 days. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalInflowAmount90D = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of credit transactions into the account in the time period of the report. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalOutflowAmount = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of credit transactions into the account in the last 30 days. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalOutflowAmount30D = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of credit transactions into the account in the last 60 days. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalOutflowAmount60D = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Total amount of credit transactions into the account in the last 90 days. This field will be empty for non-depository accounts. This field only takes into account USD transactions from the account. */
export type TotalOutflowAmount90D = {
  /** Value of amount with up to 2 decimal places. */
  amount: number;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Largest number of days between sequential transactions per calendar month */
export type BaseReportLongestGapInsights = {
  /** The start date of this time period. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date?: string;
  /** The end date of this time period. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date?: string;
  /** Largest number of days between sequential transactions for this time period. */
  days?: number | null;
  [key: string]: unknown;
};

/** The number of credits or debits out of the account. This field will only be included for depository accounts. */
export type BaseReportNumberFlowInsights = {
  /** The start date of this time period. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date: string;
  /** The end date of this time period. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date: string;
  /** The number of credits or debits out of the account for this time period. */
  count: number;
  [key: string]: unknown;
};

/** Average dollar amount of credit or debit transactions out of the account. This field will only be included for depository accounts. */
export type BaseReportAverageFlowInsights = {
  /** The start date of this time period. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date: string;
  /** The end date of this time period. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date: string;
  total_amount: CreditAmountWithCurrency;
  [key: string]: unknown;
};

