/** A date in the format YYYY-MM-DD (RFC 3339 Section 5.6). */
export type Iso8601Date = string;

/** A date in the format YYYY-MM-DD (RFC 3339 Section 5.6). */
export type Iso8601DateNullable = string | null;

/** An ISO-4217 currency code. */
export type IsoCurrencyCode = "USD";

