/** ConsumerReportPDFGetResponse defines the response schema for `/consumer_report/pdf/get` */
export type ConsumerReportPdfGetResponse = string;

/** The Check Income Insights Report for an end user. */
export type CraIncomeInsights = {
  /** The unique identifier associated with the Check Income Insights Report. */
  report_id?: string;
  /** The time when the Check Income Insights Report was generated. */
  generated_time?: string;
  /** The number of days requested by the customer for the Check Income Insights Report. */
  days_requested?: number;
  /** Client-generated identifier, which can be used by lenders to track loan applications. */
  client_report_id?: string | null;
  /** The list of Items in the report along with the associated metadata about the Item. */
  items?: (CraBankIncomeItem)[];
  user_summary?: CraIncomeInsightsUserSummary;
  /** The list of income streams for this user. */
  income_streams?: (CraIncomeStream)[];
  bank_income_summary?: CraBankIncomeSummary;
  /** If data from the report was unable to be retrieved, the warnings object will contain information about the error that caused the data to be incomplete. */
  warnings?: (CraBankIncomeWarning)[];
  [key: string]: unknown;
};

/** The details and metadata for an end user's Item. */
export type CraBankIncomeItem = {
  item_id?: ItemId;
  /** The Item's accounts that have bank income data. */
  accounts?: (CraBankIncomeAccount)[];
  /** This is a V1 (II1) field. For the V2 (II2) equivalent, use the `accounts` field. The Item's accounts that have bank income data. */
  bank_income_accounts: (CraBankIncomeAccount)[];
  /** This is a V1 (II1) field. For the V2 (II2) equivalent, use the report-level `income_streams` field. The income sources for this Item. Each entry in the array is a single income source. */
  bank_income_sources: (CraBankIncomeSource)[];
  /** The time when this Item's data was last retrieved from the financial institution. */
  last_updated_time?: string;
  /** The unique identifier of the institution associated with the Item. */
  institution_id?: string;
  /** The name of the institution associated with the Item. */
  institution_name?: string;
};

/** The Item's bank accounts that have the selected data. */
export type CraBankIncomeAccount = {
  /** Plaid’s unique identifier for the account. This value will not change unless Plaid can't reconcile the account with the data returned by the financial institution. This may occur, for example, when the name of the account changes. If this happens a new `account_id` will be assigned to the account.  If an account with a specific `account_id` disappears instead of changing, the account is likely closed. Closed accounts are not returned by the Plaid API.  Like all Plaid identifiers, the `account_id` is case sensitive. */
  account_id?: string;
  /** The last 2-4 alphanumeric characters of an account's official account number. Note that the mask may be non-unique between an Item's accounts, and it may also not match the mask that the bank displays to the user. */
  mask: string | null;
  metadata: CraBankIncomeAccountMetadata;
  /** The name of the bank account. */
  name: string;
  /** The official name of the bank account. */
  official_name: string | null;
  subtype: DepositoryAccountSubtype;
  type: CreditBankIncomeAccountType;
  /** Data returned by the financial institution about the account owner or owners. Identity information is optional, so field may return an empty array. */
  owners: (Owner)[];
};

/** An object containing metadata about the extracted account. */
export type CraBankIncomeAccountMetadata = {
  /** The date of the earliest extracted transaction, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format ("yyyy-mm-dd"). */
  start_date: string | null;
  /** The date of the most recent extracted transaction, in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format ("yyyy-mm-dd"). */
  end_date: string | null;
};

/** Detailed information for the income source. */
export type CraBankIncomeSource = {
  /** The account ID with which this income source is associated. */
  account_id?: string;
  /** A unique identifier for an income source. If the report is regenerated and a new `report_id` is created, the new report will have a new set of `income_source_id`s. */
  income_source_id?: string;
  /** The most common name or original description for the underlying income transactions. */
  income_description?: string;
  income_category?: CreditBankIncomeCategory;
  /** Minimum of all dates within the specific income sources in the user's bank account for days requested by the client. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date?: string;
  /** Maximum of all dates within the specific income sources in the user’s bank account for days requested by the client. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date?: string;
  pay_frequency?: CreditBankIncomePayFrequency;
  /** Total amount of earnings in the user’s bank account for the specific income source for days requested by the client. */
  total_amount?: number;
  iso_currency_code?: CreditIsoCurrencyCode;
  unofficial_currency_code?: CreditUnofficialCurrencyCode;
  /** Number of transactions for the income source within the start and end date. */
  transaction_count?: number;
  /** The expected date of the end user’s next paycheck for the income source. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  next_payment_date?: string | null;
  status?: CraBankIncomeStatus;
  /** An estimate of the average gross monthly income based on the historical net amount and income category for the income source(s). */
  historical_average_monthly_gross_income?: number | null;
  /** The average monthly net income amount estimated based on the historical data for the income source(s). */
  historical_average_monthly_income?: number | null;
  /** The predicted average monthly net income amount for the income source(s). */
  forecasted_average_monthly_income?: number | null;
  /** The prediction interval(s) for the forecasted average monthly income. */
  forecasted_average_monthly_income_prediction_intervals: (CraPredictionInterval)[];
  employer?: CraBankIncomeEmployer;
  income_provider: CraBankIncomeIncomeProvider;
  historical_summary?: (CraBankIncomeHistoricalSummary)[];
  [key: string]: unknown;
};

/** The object containing prediction interval data. */
export type CraPredictionInterval = {
  /** The lower bound of the predicted attribute for the given probability. */
  lower_bound?: number | null;
  /** The upper bound of the predicted attribute for the given probability. */
  upper_bound?: number | null;
  /** The probability of the actual value of the attribute falling within the upper and lower bound. This is a percentage represented as a value between 0 and 1. */
  probability?: number | null;
  [key: string]: unknown;
};

/** The object containing employer data. */
export type CraBankIncomeEmployer = {
  /** The name of the employer. */
  name: string | null;
  [key: string]: unknown;
};

/** The object containing data about the income provider. */
export type CraBankIncomeIncomeProvider = {
  /** The name of the income provider. */
  name: string;
  /** Indicates whether the income provider name is normalized by comparing it against a canonical set of known providers. */
  is_normalized: boolean;
  [key: string]: unknown;
};

/** This is a V1 (II1) schema. For the V2 (II2) equivalent, use `CraIncomeInsightsUserSummary`. Summary for income across all income sources and items (max history of 730 days). */
export type CraBankIncomeSummary = {
  /** Total amount of earnings across all the income sources in the end user's Items for the days requested by the client. This can contain multiple amounts, with each amount denominated in one unique currency. */
  total_amounts?: (CreditAmountWithCurrency)[];
  /** The earliest date within the days requested in which all income sources identified by Plaid appear in a user's account. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date?: string;
  /** The latest date in which all income sources identified by Plaid appear in the user's account. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date?: string;
  /** Number of income sources per end user. */
  income_sources_count?: number;
  /** Number of income categories per end user. */
  income_categories_count?: number;
  /** Number of income transactions per end user. */
  income_transactions_count?: number;
  /** An estimate of the average gross monthly income based on the historical net amount and income category for the income source(s). The average monthly income is calculated based on the lifetime of the income stream, rather than the entire historical period included in the scope of the report. */
  historical_average_monthly_gross_income?: (CreditAmountWithCurrency)[];
  /** The average monthly income amount estimated based on the historical data for the income source(s). The average monthly income is calculated based on the lifetime of the income stream, rather than the entire historical period included in the scope of the report. */
  historical_average_monthly_income?: (CreditAmountWithCurrency)[];
  /** The predicted average monthly income amount for the income source(s). */
  forecasted_average_monthly_income?: (CreditAmountWithCurrency)[];
  /** An estimate of the annual gross income for the income source, calculated by multiplying the `historical_average_monthly_gross_income` by 12. */
  historical_annual_gross_income?: (CreditAmountWithCurrency)[];
  /** An estimate of the annual net income for the income source, calculated by multiplying the `historical_average_monthly_income` by 12. */
  historical_annual_income?: (CreditAmountWithCurrency)[];
  /** The predicted average annual income amount for the income source(s). */
  forecasted_annual_income?: (CreditAmountWithCurrency)[];
  historical_summary?: (CraBankIncomeHistoricalSummary)[];
  [key: string]: unknown;
};

/** The end user's monthly summary for the income source(s). */
export type CraBankIncomeHistoricalSummary = {
  /** Total amount of earnings for the income source(s) of the user for the month in the summary. This can contain multiple amounts, with each amount denominated in one unique currency. */
  total_amounts?: (CreditAmountWithCurrency)[];
  /** The start date of the period covered in this monthly summary. This date will be the first day of the month, unless the month being covered is a partial month because it is the first month included in the summary and the date range being requested does not begin with the first day of the month. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date?: string;
  /** The end date of the period included in this monthly summary. This date will be the last day of the month, unless the month being covered is a partial month because it is the last month included in the summary and the date range being requested does not end with the last day of the month. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date?: string;
  transactions?: (CraBankIncomeTransaction)[];
  [key: string]: unknown;
};

/** The transactions data for the end user's income source(s). */
export type CraBankIncomeTransaction = {
  /** The unique ID of the transaction. Like all Plaid identifiers, the `transaction_id` is case sensitive. */
  transaction_id: string;
  /** The settled value of the transaction, denominated in the transaction's currency as stated in `iso_currency_code` or `unofficial_currency_code`. Positive values when money moves out of the account; negative values when money moves in. For example, credit card purchases are positive; credit card payment, direct deposits, and refunds are negative. */
  amount: number;
  /** For pending transactions, the date that the transaction occurred; for posted transactions, the date that the transaction posted. Both dates are returned in an ISO 8601 format (YYYY-MM-DD). */
  date: string;
  /** The merchant name or transaction description. This is a legacy field that is no longer maintained. For merchant name, use the `merchant_name` field; for description, use the `original_description` field. */
  name?: string;
  /** The string returned by the financial institution to describe the transaction. */
  original_description: string | null;
  /** When true, identifies the transaction as pending or unsettled. Pending transaction details (name, type, amount, category ID) may change before they are settled. */
  pending: boolean;
  /** The check number of the transaction. This field is only populated for check transactions. */
  check_number?: string | null;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  bonus_type?: CraBankIncomeBonusType;
  [key: string]: unknown;
};

/** The type of bonus that this transaction represents, if it is a bonus. `BONUS_INCLUDED`: Bonus is included in this transaction along with the normal pay `BONUS_ONLY`: This transaction is a standalone bonus */
export type CraBankIncomeBonusType = "BONUS_INCLUDED" | "BONUS_ONLY" | null | null;

/** The status of the income sources. `ACTIVE`: The income source is active. `INACTIVE`: The income source is inactive. `UNKNOWN`: The income source status is unknown. */
export type CraBankIncomeStatus = "ACTIVE" | "INACTIVE" | "UNKNOWN";

/** Aggregated summary of all income streams for this user. */
export type CraIncomeInsightsUserSummary = {
  /** List of a user's aggregated income metrics for each currency. */
  income_metrics: (CraIncomeMetrics)[];
  [key: string]: unknown;
};

/** Modeled income metrics for a given income stream or user summary. */
export type CraIncomeMetrics = {
  current: CraCurrentModeledIncome;
  projected: CraProjectedModeledIncome;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  [key: string]: unknown;
};

/** Modeled estimate of current income based on recently observed income transactions. */
export type CraCurrentModeledIncome = {
  monthly: CraMonthlyIncomeValues;
  annual: CraAnnualIncomeValues;
  [key: string]: unknown;
};

/** Forward-looking modeled estimate of income based on recent income transactions and trends in active streams. */
export type CraProjectedModeledIncome = {
  monthly: CraMonthlyIncomeValues;
  annual: CraAnnualIncomeValues;
  [key: string]: unknown;
};

/** Modeled estimate of the monthly income. */
export type CraMonthlyIncomeValues = {
  /** Gross Income modeled from trends of observed transactions. */
  gross_income: number;
  /** Net Income estimated from observed transactions. */
  net_income: number;
  [key: string]: unknown;
};

/** Modeled estimate of the annual income. */
export type CraAnnualIncomeValues = {
  /** Gross Income modeled from trends of observed transactions. */
  gross_income: number;
  /** Net Income estimated from observed transactions. */
  net_income: number;
  [key: string]: unknown;
};

/** An income stream detected for the user. */
export type CraIncomeStream = {
  /** A unique identifier for an income stream. If the report is regenerated and a new `report_id` is created, the new report will have a new set of `income_stream_id`s. */
  income_stream_id: string;
  /** Minimum of all dates within the specific income stream for days requested by the client. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  start_date: string;
  /** Maximum of all dates within the specific income stream for days requested by the client. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  end_date: string;
  /** The most common name or original description for the underlying income transactions. */
  description: string;
  insights: CraIncomeStreamInsights;
  income_metrics: CraIncomeMetrics;
  /** The transactions data for the income stream ordered by ascending date. */
  transactions: (CraIncomeTransaction)[];
  [key: string]: unknown;
};

/** Modeled insights for a given income stream. */
export type CraIncomeStreamInsights = {
  income_category: CraIncomeCategory;
  pay_frequency: CreditBankIncomePayFrequency;
  income_provider: CraBankIncomeIncomeProvider;
  status: CraBankIncomeStatus;
  next_payment: CraIncomeNextPayment;
  [key: string]: unknown;
};

/** The income category for a given stream. The streams returned in the response will be filtered based on these primary and secondary income categories.  See the [Income V2 Category Taxonomy](https://plaid.com/documents/income-v2-category-taxonomy.csv) for a full list of income categories. */
export type CraIncomeCategory = {
  /** A high level category that communicates the broad category of the stream. */
  primary: string;
  /** A granular category conveying the stream's intent. */
  secondary: string;
  [key: string]: unknown;
};

/** Metadata of the income stream's next payment. */
export type CraIncomeNextPayment = {
  /** The expected date of the income stream's next payment. The date will be returned in an ISO 8601 format (YYYY-MM-DD). */
  date: string;
  [key: string]: unknown;
};

/** Metadata on whether this income transaction is an outlier. */
export type CraIncomeTransactionOutlier = {
  /** Indicates whether an income transaction amount is unusually high compared to the amounts for that stream. */
  is_outlier: boolean;
  /** The amount that the transaction differs from the stream average transaction amount. */
  amount?: number | null;
  [key: string]: unknown;
};

/** The transaction data for an income stream. */
export type CraIncomeTransaction = {
  /** The unique ID of the transaction. Like all Plaid identifiers, the `transaction_id` is case sensitive. */
  transaction_id: string;
  item_id: ItemId;
  /** Plaid's unique identifier for the account. This value will not change unless Plaid can't reconcile the account with the data returned by the financial institution. This may occur, for example, when the name of the account changes. If this happens a new `account_id` will be assigned to the account.  If an account with a specific `account_id` disappears instead of changing, the account is likely closed. Closed accounts are not returned by the Plaid API.  Like all Plaid identifiers, the `account_id` is case sensitive. */
  account_id: string;
  /** The settled value of the transaction, denominated in the transaction's currency as stated in `iso_currency_code` or `unofficial_currency_code`. Positive values when money moves out of the account; negative values when money moves in. For example, credit card purchases are positive; credit card payment, direct deposits, and refunds are negative. */
  amount: number;
  /** For pending transactions, the date that the transaction occurred; for posted transactions, the date that the transaction posted. Both dates are returned in an ISO 8601 format (YYYY-MM-DD). */
  date: string;
  /** The string returned by the financial institution to describe the transaction. */
  original_description: string;
  iso_currency_code: CreditIsoCurrencyCode;
  unofficial_currency_code: CreditUnofficialCurrencyCode;
  outlier: CraIncomeTransactionOutlier;
  [key: string]: unknown;
};

/** Defines configuration options to generate Income Insights. */
export type CraCheckReportIncomeInsightsGetOptions = {
  income_insights_filter?: IncomeInsightsFilter;
  income_insights_version: IncomeInsightsVersion;
};

/** The warning associated with the data that was unavailable. */
export type CraBankIncomeWarning = {
  warning_type?: CreditBankIncomeWarningType;
  warning_code?: CraBankIncomeWarningCode;
  cause?: CraBankIncomeCause;
  [key: string]: unknown;
};

/** The warning code identifies a specific kind of warning. `IDENTITY_UNAVAILABLE`: Unable to extract identity for the Item `TRANSACTIONS_UNAVAILABLE`: Unable to extract transactions for the Item `REPORT_DELETED`: Report deleted due to customer or consumer request `DATA_UNAVAILABLE`: No relevant data was found for the Item */
export type CraBankIncomeWarningCode = "IDENTITY_UNAVAILABLE" | "TRANSACTIONS_UNAVAILABLE" | "REPORT_DELETED" | "DATA_UNAVAILABLE";

/** An error object and associated `item_id` used to identify a specific Item and error when a batch operation operating on multiple Items has encountered an error in one of the Items. */
export type CraBankIncomeCause = {
  error_type: CreditBankIncomeErrorType;
  /** We use standard HTTP response codes for success and failure notifications, and our errors are further classified by `error_type`. In general, 200 HTTP codes correspond to success, 40X codes are for developer- or user-related failures, and 50X codes are for Plaid-related issues. Error fields will be `null` if no error has occurred. */
  error_code: string;
  /** A developer-friendly representation of the error code. This may change over time and is not safe for programmatic use. */
  error_message: string;
  /** A user-friendly representation of the error code. null if the error is not related to user action. This may change over time and is not safe for programmatic use. */
  display_message: string;
  [key: string]: unknown;
};

/** CraCheckReportCreateRequest defines the request schema for `/cra/check_report/create`. */
export type CraCheckReportCreateRequest = {
  client_id?: ApiClientId;
  secret?: ApiSecret;
  user_id?: NewUserId;
  user_token?: UserToken;
  /** The destination URL to which webhooks will be sent  */
  webhook: string;
  /** The number of days of data to request for the report. Default value is 365; maximum is 731; minimum is 180. If a value lower than 180 is provided, a minimum of 180 days of history will be requested. */
  days_requested: number;
  /** The minimum number of days of data required for the report to be successfully generated. */
  days_required?: number;
  /** Client-generated identifier, which can be used by lenders to track loan applications. */
  client_report_id?: string | null;
  /** Specifies a list of products that will be eagerly generated when creating the report (in addition to the Base Report, which is always eagerly generated). These products will be made available before a success webhook is sent. Use this option to minimize response latency for product `/get` endpoints. Note that specifying `cra_partner_insights` in this field will trigger a billable event. Other products are not billed until the respective reports are fetched via product-specific `/get` endpoints. */
  products?: (Products)[] | null;
  base_report?: CraCheckReportCreateBaseReportOptions;
  cashflow_insights?: CraCheckReportCashflowInsightsGetOptions;
  partner_insights?: CraCheckReportCreatePartnerInsightsOptions;
  lend_score?: CraCheckReportLendScoreGetOptions;
  network_insights?: CraCheckReportNetworkInsightsGetOptions;
  /** Indicates that investment data should be extracted from the linked account(s). */
  include_investments?: boolean | null;
  income_insights?: CraCheckReportIncomeInsightsGetOptions;
  consumer_report_permissible_purpose: ConsumerReportPermissiblePurpose;
};

/** CraCheckReportCreateResponse defines the response schema for `/cra/check_report/create`. */
export type CraCheckReportCreateResponse = {
  request_id?: RequestId;
  [key: string]: unknown;
};

