/** Your Plaid API `secret`. The `secret` is required and may be provided either in the `PLAID-SECRET` header or as part of a request body as either `secret` or `client_secret`. */
export type OauthApiSecret = string;

/** A JSON string containing a space-separated list of scopes associated with this token, in the format described in [https://datatracker.ietf.org/doc/html/rfc6749#section-3.3](https://datatracker.ietf.org/doc/html/rfc6749#section-3.3). Currently accepted values are:  `user:read` allows reading user data. `user:write` allows writing user data. `exchange` allows exchanging a token using the `urn:plaid:params:oauth:user-token` grant type. `mcp:dashboard` allows access to the MCP dashboard server. */
export type OAuthScope = string;

/** OAuth error code */
export type OAuthErrorCode = "invalid_request" | "invalid_client" | "invalid_grant" | "unauthorized_client" | "invalid_scope" | "unsupported_grant_type";

/** A human-readable description of the error */
export type OAuthErrorDescription = string;

/** A URI identifying the specific error */
export type OAuthErrorUri = string;

/** Refresh token for OAuth */
export type OAuthRefreshToken = string;

/** Access token for OAuth */
export type OAuthAccessToken = string;

/** An OAuth token of any type (`refresh_token`, `access_token`, etc) */
export type OAuthAnyToken = string;

/** The type of OAuth grant being requested:  `client_credentials` allows exchanging a client id and client secret for a refresh and access token. `refresh_token` allows refreshing an access token using a refresh token. When using this grant type, only the `refresh_token` field is required (along with the `client_id` and `client_secret`). `urn:ietf:params:oauth:grant-type:token-exchange` allows exchanging a subject token for an OAuth token. When using this grant type, the `audience`, `subject_token` and `subject_token_type` fields are required. These grants are defined in their respective RFCs. `refresh_token` and `client_credentials` are defined in RFC 6749 and `urn:ietf:params:oauth:grant-type:token-exchange` is defined in RFC 8693. */
export type OAuthGrantType = "refresh_token" | "urn:ietf:params:oauth:grant-type:token-exchange" | "client_credentials";

/** The type of the subject token. `urn:plaid:params:tokens:user` allows exchanging a Plaid-issued user token for an OAuth token. When using this token type, `audience` must be the same as the `client_id`. `subject_token` must be a Plaid-issued user token issued from the `/user/create` endpoint. `urn:plaid:params:oauth:user-token` allows exchanging a refresh token for an OAuth token to another `client_id`. The other `client_id` is provided in `audience`. `subject_token` must be an OAuth refresh token issued from the `/oauth/token` endpoint. `urn:plaid:params:credit:multi-user` allows exchanging a Plaid-issued user token for an OAuth token. When using this token type, `audience` may be a client id or a supported CRA partner URN. `audience` supports a comma-delimited list of clients. When multiple clients are specified in the `audience` a multi-party token is created which can be used by all parties in the audience in conjunction with their `client_id` and `client_secret`. */
export type OAuthSubjectTokenType = "urn:plaid:params:tokens:user" | "urn:plaid:params:oauth:user-token" | "urn:plaid:params:credit:multi-user";

/** OAuth token grant request. */
export type OAuthTokenRequest = {
  grant_type: OAuthGrantType;
  client_id?: ApiClientId;
  client_secret?: OauthApiSecret;
  secret?: OauthApiSecret;
  scope?: OAuthScope;
  refresh_token?: OAuthRefreshToken;
  /** URI of the target resource server */
  resource?: string;
  /** Used when exchanging a token. The meaning depends on the `subject_token_type`:  - For `urn:plaid:params:tokens:user`: Must be the same as the `client_id`. - For `urn:plaid:params:oauth:user-token`: The other `client_id` to exchange tokens to. - For `urn:plaid:params:credit:multi-user`:  a `client_id` or one of the supported CRA partner URNs: `urn:plaid:params:cra-partner:experian`, `urn:plaid:params:cra-partner:fannie-mae`, or `urn:plaid:params:cra-partner:freddie-mac`. */
  audience?: string;
  /** Token representing the subject. The `subject token` must be an OAuth refresh token issued from the `/oauth/token` endpoint. The meaning depends on the `subject_token_type`. */
  subject_token?: string;
  subject_token_type?: OAuthSubjectTokenType;
};

/** OAuth token grant success response */
export type OAuthTokenResponse = {
  access_token: OAuthAccessToken;
  refresh_token: OAuthRefreshToken;
  /** Type of token the access token is. Currently it is always Bearer */
  token_type: string;
  /** Time remaining in seconds before expiration */
  expires_in: number;
  request_id: RequestId;
  [key: string]: unknown;
};

/** OAuth token introspect request. */
export type OAuthIntrospectRequest = {
  token: OAuthAnyToken;
  client_id?: ApiClientId;
  client_secret?: OauthApiSecret;
  secret?: OauthApiSecret;
};

/** OAuth token introspect response */
export type OAuthIntrospectResponse = {
  /** Boolean indicator of whether or not the presented token is currently active. A `true` value indicates that the token has been issued, has not been revoked, and is within the time window of validity. */
  active: boolean;
  scope?: OAuthScope;
  client_id?: ApiClientId;
  /** Expiration time as UNIX timestamp since January 1 1970 UTC */
  exp?: number;
  /** Issued at time as UNIX timestamp since January 1 1970 UTC */
  iat?: number;
  /** Subject of the token */
  sub?: string;
  /** Audience of the token */
  aud?: string;
  /** Issuer of the token */
  iss?: string;
  /** Type of the token */
  token_type?: string;
  /** User ID of the token */
  user_id?: string;
  request_id: RequestId;
  [key: string]: unknown;
};

/** OAuth error response */
export type OAuthErrorResponse = {
  error?: OAuthErrorCode;
  error_description?: OAuthErrorDescription;
  error_uri?: OAuthErrorUri;
  request_id: RequestId;
  [key: string]: unknown;
};

/** OAuth token revoke request */
export type OAuthRevokeRequest = {
  token: OAuthAnyToken;
  client_id?: ApiClientId;
  client_secret?: OauthApiSecret;
  secret?: OauthApiSecret;
};

/** Successful OAuth token revoke response */
export type OAuthRevokeResponse = {
  request_id: RequestId;
  [key: string]: unknown;
};

